<script setup lang="ts">
import { computed, ref, onMounted, onBeforeUnmount } from 'vue'
import { cloneJson } from '../render/clone'
import { solve,solveNodeAreas,type FlexContainer } from '../render/flexLayout'
import { collectRowDividers,collectColumnDividers,findContainerById,ensureResizePair,moveLeaf,resolveDropTarget,leafOffset } from './algorithms/flexTree'
import { resolveDragTree,activateCornerGrow,ratioStartT,growStartT,type DragSession } from './algorithms/flexEditDragSession'
import { EDGE_HANDLES,CORNER_HANDLES,gripOffsetStyle,movedPastThreshold,resolveCornerAxisLock } from './algorithms/flexEditGeometry'
const props=defineProps<{tree:FlexContainer;selected:string|null;disabled?:boolean}>(),emit=defineEmits<{preview:[tree:FlexContainer|null];commit:[tree:FlexContainer];insert:[type:string,parent:string,index:number,columns:number]}>();const root=ref<HTMLElement|null>(null),draft=ref<FlexContainer|null>(null),drop=ref<ReturnType<typeof resolveDropTarget>>(null)
let session:DragSession|null=null,pointerId=-1,lastPointer={x:0,y:0},startClient={x:0,y:0},activated=false
const tree=computed(()=>draft.value||props.tree),placements=computed(()=>new Map(solve(tree.value).map(p=>[p.block_id,p.rect]))),rows=computed(()=>collectRowDividers(tree.value,placements.value)),columns=computed(()=>collectColumnDividers(tree.value,placements.value)),selectedRect=computed(()=>props.selected?placements.value.get(props.selected):null)
function pointer(e:PointerEvent|DragEvent){const r=root.value!.getBoundingClientRect();return{x:(e.clientX-r.left)/r.width,y:(e.clientY-r.top)/r.height}}
function attach(e:PointerEvent){e.preventDefault();e.stopPropagation();pointerId=e.pointerId;startClient={x:e.clientX,y:e.clientY};activated=false;window.addEventListener('pointermove',move);window.addEventListener('pointerup',up);window.addEventListener('pointercancel',cancel);window.addEventListener('keydown',key)}
function startResize(e:PointerEvent,axis:'x'|'y',side:'before'|'after',corner?:'before'|'after'){if(props.disabled||!props.selected)return;const pair=ensureResizePair(cloneJson(props.tree),props.selected,axis,side);if(!pair)return;startDivider(e,axis,pair.containerId,pair.index,pair.tree,corner)}
function startDivider(e:PointerEvent,axis:'x'|'y',id:string,index:number,base=cloneJson(props.tree),corner?:'before'|'after'){if(props.disabled)return;const node=findContainerById(base,id),area=solveNodeAreas(base).get(id);if(!node||!area)return;const origin=pointer(e),gate={activated:false,deferPreview:true,startClientX:e.clientX,startClientY:e.clientY};if(axis==='x'){const ratios=node.ratios||node.children.map(()=>100/node.children.length);session={kind:'ratio',baseTree:base,rowId:id,leftIndex:index,rowX:area.x,rowW:area.w,startT:ratioStartT(ratios,index),originX:origin.x,...gate}}else{session={kind:'grow',baseTree:base,columnId:id,topIndex:index,colY:area.y,colH:area.h,startT:growStartT(node.children.map(c=>c.grow||1),index),originY:origin.y,pendingCorner:corner&&props.selected?{blockId:props.selected,sideX:corner,originX:origin.x}:undefined,...gate}}attach(e)}
function startMove(e:PointerEvent){if(props.disabled||!props.selected||!selectedRect.value)return;const origin=pointer(e),rect=selectedRect.value;if(e.altKey){const offset=leafOffset(props.tree,props.selected);session={kind:'offset',baseTree:cloneJson(props.tree),blockId:props.selected,baseX:offset.x,baseY:offset.y,startX:origin.x,startY:origin.y}}else{session={kind:'reorder',blockId:props.selected,drop:null,grabOffsetX:origin.x-rect.x,grabOffsetY:origin.y-rect.y,ghostW:rect.w,ghostH:rect.h,pointerX:origin.x,pointerY:origin.y}}attach(e)}
function move(e:PointerEvent){if(e.pointerId!==pointerId||!session)return;if(!activated&&!movedPastThreshold(startClient.x,startClient.y,e.clientX,e.clientY))return;activated=true;lastPointer=pointer(e);if(session.kind==='grow'&&session.pendingCorner)session=activateCornerGrow(session,resolveCornerAxisLock(e.clientX-startClient.x,e.clientY-startClient.y));if(session.kind==='reorder'){drop.value=resolveDropTarget({root:props.tree,placements:placements.value,pointer:lastPointer,draggedBlockId:session.blockId});return}const next=resolveDragTree(session,lastPointer);if(next){draft.value=next;emit('preview',next)}}
function detach(){window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);window.removeEventListener('pointercancel',cancel);window.removeEventListener('keydown',key)}
function finish(commit:boolean){let next=draft.value;if(commit&&activated&&session?.kind==='reorder'&&drop.value)next=moveLeaf(cloneJson(props.tree),session.blockId,drop.value.parentId,drop.value.index);detach();session=null;pointerId=-1;draft.value=null;drop.value=null;emit('preview',null);if(commit&&activated&&next)emit('commit',next)}
function up(e:PointerEvent){if(e.pointerId===pointerId)finish(true)}function cancel(){finish(false)}function key(e:KeyboardEvent){if(e.key==='Escape'){e.preventDefault();cancel()}}
function dragOver(e:DragEvent){if(props.disabled||!e.dataTransfer?.types.includes('application/aippt-block'))return;e.preventDefault();drop.value=resolveDropTarget({root:props.tree,placements:placements.value,pointer:pointer(e),mode:'insert'})}
function insertDrop(e:DragEvent){e.preventDefault();try{const raw=e.dataTransfer?.getData('application/aippt-block');if(!raw||!drop.value)return;const payload=JSON.parse(raw);emit('insert',payload.type,drop.value.parentId,drop.value.index,Number(payload.columns||1))}finally{drop.value=null}}
// 透明编辑层与内容块是兄弟节点，从画布父级接收拖入事件。
let dragHost:HTMLElement|null=null
function dragLeave(e:DragEvent){if(!dragHost?.contains(e.relatedTarget as Node|null))drop.value=null}
onMounted(()=>{dragHost=root.value?.parentElement||null;dragHost?.addEventListener('dragover',dragOver);dragHost?.addEventListener('drop',insertDrop);dragHost?.addEventListener('dragleave',dragLeave)})
onBeforeUnmount(()=>{detach();dragHost?.removeEventListener('dragover',dragOver);dragHost?.removeEventListener('drop',insertDrop);dragHost?.removeEventListener('dragleave',dragLeave)})
</script>
<template><div ref="root" class="flex-edit"><template v-if="!disabled"><button v-for="(d,i) in rows" :key="'r'+i" class="divider vertical" aria-label="拖动列分隔线" :style="{left:d.x*100+'%',top:d.y*100+'%',height:d.h*100+'%'}" @pointerdown="startDivider($event,'x',d.rowId,d.leftIndex)"/><button v-for="(d,i) in columns" :key="'c'+i" class="divider horizontal" aria-label="拖动行分隔线" :style="{left:d.x*100+'%',top:d.y*100+'%',width:d.w*100+'%'}" @pointerdown="startDivider($event,'y',d.columnId,d.topIndex)"/><template v-if="selectedRect"><button class="grip" :style="gripOffsetStyle(selectedRect)" title="拖动跨容器移动；Alt+拖动平移；Esc取消" aria-label="移动内容块" @pointerdown="startMove">⠿</button><button v-for="h in EDGE_HANDLES" :key="h.key" :class="['edge',h.axis==='x'?'vertical':'horizontal']" :style="h.style(selectedRect)" :aria-label="h.title" @pointerdown="startResize($event,h.axis,h.side)"/><button v-for="h in selectedRect.w>=.32?CORNER_HANDLES:[]" :key="h.key" class="corner" :style="h.style(selectedRect)" aria-label="拖动角点调整大小" @pointerdown="startResize($event,'y',h.sideY,h.sideX)"/></template><div v-if="drop" class="drop-line" :style="{left:drop.line.x*100+'%',top:drop.line.y*100+'%',width:Math.max(drop.line.w,.002)*100+'%',height:Math.max(drop.line.h,.002)*100+'%'}"/></template></div></template>
<style scoped>.flex-edit{position:absolute;inset:0;pointer-events:none;z-index:8}.flex-edit button{position:absolute;padding:0;border:0;background:transparent;pointer-events:auto;touch-action:none}.divider{opacity:.2}.divider:hover,.divider:focus-visible{background:#409eff;opacity:.8}.vertical{width:10px;transform:translateX(-50%);cursor:col-resize}.horizontal{height:10px;transform:translateY(-50%);cursor:row-resize}.edge::after{content:'';position:absolute;background:#409eff;border-radius:3px}.edge.vertical::after{left:4px;top:20%;width:3px;height:60%}.edge.horizontal::after{top:4px;left:20%;width:60%;height:3px}.grip{width:22px;height:22px;background:#409eff!important;color:#fff;cursor:grab;border-radius:4px}.corner{width:12px;height:12px;border:2px solid #409eff!important;background:#fff!important;transform:translate(-50%,-50%);cursor:nwse-resize}.drop-line{position:absolute;background:#409eff;pointer-events:none}</style>
